examples.setup:
@State private var actions = [
    MonarchRuleAction(id: "1", type: "set_team", parameters: ["teamId": .option("billing")]),
    MonarchRuleAction(id: "2", type: "notify", parameters: ["to": .option("person"), "message": .text("")]),
]
private let types = [
    MonarchActionType(id: "set_team", label: "Set team", group: "Routing", parameters: [
        MonarchActionParameter(key: "teamId", label: "Team", kind: .select([
            MonarchComboboxOption(id: "support", label: "Support"),
            MonarchComboboxOption(id: "billing", label: "Billing"),
        ]), isRequired: true),
    ]),
    MonarchActionType(id: "assign_round_robin", label: "Assign in turn", description: "The next available person in the team, in turn.", group: "Routing", parameters: [
        MonarchActionParameter(key: "teamId", label: "Team", kind: .select([
            MonarchComboboxOption(id: "support", label: "Support"),
            MonarchComboboxOption(id: "billing", label: "Billing"),
        ]), emptyLabel: "The current team"),
    ]),
    MonarchActionType(id: "set_priority", label: "Set priority", group: "Fields", parameters: [
        MonarchActionParameter(key: "priority", label: "Priority", kind: .select([
            MonarchComboboxOption(id: "low", label: "Low"),
            MonarchComboboxOption(id: "high", label: "High"),
        ]), isRequired: true),
    ]),
    MonarchActionType(id: "add_tags", label: "Add tags", group: "Fields", parameters: [
        MonarchActionParameter(key: "tags", label: "Tags", kind: .tags(suggestions: []), isRequired: true, prompt: "Type a tag and press Enter"),
    ], defaults: ["tags": .list([])]),
    MonarchActionType(id: "notify", label: "Notify people", group: "Messages", parameters: [
        MonarchActionParameter(key: "to", label: "Notify", kind: .select([
            MonarchComboboxOption(id: "assignee", label: "Assignee"),
            MonarchComboboxOption(id: "team", label: "Everyone in the team"),
            MonarchComboboxOption(id: "person", label: "A specific person"),
        ]), isRequired: true),
        MonarchActionParameter(key: "personId", label: "Person", kind: .select([
            MonarchComboboxOption(id: "p1", label: "Jo Park"),
            MonarchComboboxOption(id: "p2", label: "Ana Ruiz"),
        ]), isRequired: true, visibleWhen: { $0["to"] == .option("person") }),
        MonarchActionParameter(key: "message", label: "Message", kind: .multilineText, isRequired: true),
    ], defaults: ["to": .option("assignee"), "message": .text("")]),
    MonarchActionType(id: "external_issue", label: "Create an issue in another app", group: "Messages", isDisabled: true, disabledReason: "The connection is not set up."),
]

@State private var actions = [MonarchRuleAction(id: "a1", type: "note")]
@State private var showsErrors = false
private let types = [
    MonarchActionType(id: "note", label: "Add a note", parameters: [
        MonarchActionParameter(key: "text", label: "Note", kind: .multilineText, isRequired: true),
    ]),
]

examples.code:
VStack(alignment: .leading) {
    MonarchActionEditor(actions: $actions, types: types, showsErrors: showsErrors)
    MonarchButton("Save", variant: .primary) {
        showsErrors = !MonarchActionEditor.problems(of: actions, types: types).isEmpty
    }
}
